// Consumer app composition. Server projections remain the only commercial authority.
// The existing views module supplies shared interpretation and receipt disclosures.
import {createViews,escape as e,dollars as money,ruleText,statusLabel,participantOutcome} from './views.js';
const date=v=>v?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(v)):'Dates to come';
const time=v=>v?e(new Date(v).toLocaleString()):'Not yet checked';
const heading=(title,sub='')=>`<div class="app-heading"><h1 tabindex="-1">${e(title)}</h1>${sub?`<p>${e(sub)}</p>`:''}</div>`;
export function budgetStatement(statement,maximum,preferred=''){
 const amount=v=>{const n=Number(v);if(String(v).trim()===''||!Number.isFinite(n)||n<0||n>100000||Math.abs(n*100-Math.round(n*100))>1e-7)throw Error('Enter an amount in USD using whole cents.');return n;};
 const max=amount(maximum),target=String(preferred).trim()===''?null:amount(preferred);
 if(target!==null&&target>max)throw Error('Your comfortable spend must be at or below your maximum.');
 return `My hard maximum is $${max.toFixed(2)} for my individual package share.${target===null?'':` I would prefer $${target.toFixed(2)}.`} ${String(statement).trim()||'No extra preferences.'}`;
}
function needsPath(step){return `<ol class="needs-path" aria-label="Needs review progress">${['Your needs','Price context','Your boundaries'].map((label,i)=>`<li ${i+1===step?'aria-current="step"':''}><span aria-hidden="true">${i+1}</span>${label}</li>`).join('')}</ol>`;}
function priceContext(guide,expanded=false){
 if(!guide)return '<section class="needs-price-context"><h2>Your share for this plan</h2><p>Prices aren’t available right now. You can still set your own limit.</p></section>';
 const range=(lo,hi)=>lo===hi?money(lo):money(lo)+'–'+money(hi);
 const extras=[guide.rentalsIncluded?'required rentals':'rentals priced separately',guide.ownBedIncluded?'required own-bed supplement':'own-bed supplement priced separately'];
 return `<section class="needs-price-context" aria-label="Package price context"><div class="price-context-label"><span>Price guide · your share</span><span>USD</span></div>${guide.options.length?`<p class="price-guide-range">${range(guide.minShareCents,guide.maxShareCents)}</p><p class="price-guide-scope">For ${guide.groupSize} people · lodging, parking & lift ticket${guide.rentalsIncluded?' + your rentals':''}${guide.ownBedIncluded?' + your own-bed supplement':''}</p>`:'<h2>No matching estimates yet</h2><p>No catalog option meets the quality, merchant and must-have conditions checked here. Your limits stay yours.</p>'}<p class="small">Estimates only, not a confirmed group fit.${guide.joinedCount<guide.groupSize?` Assumes ${guide.groupSize} people; ${guide.joinedCount} joined.`:''}</p><details class="price-guide-details" ${expanded?'open':''}><summary>Compare prices & what’s included</summary><div class="price-guide-options">${guide.options.map(o=>`<article><div class="price-option-heading"><h3>${e(o.name)}</h3><strong>${range(o.minShareCents,o.maxShareCents)}</strong></div><p>${date(o.startDate)} – ${date(o.endDate)}, ${new Date(o.startDate).getUTCFullYear()}<br>★ ${o.rating.toFixed(1)} · ${o.reviewCount} reviews · ${o.distanceMinutes} min to lifts</p><p>${o.refundPercent}% refund by ${date(o.cancelBy)}</p><p class="small">${guide.rentalsIncluded?'Rentals included':'Rentals +'+money(o.rentalPriceCents)} · ${guide.ownBedIncluded?'Own-bed supplement included':'Own-bed supplement +'+money(o.bedSupplementCents)}</p></article>`).join('')}</div><p class="small">${e(extras.join(' · '))}. Transport, meals and costs outside the listed package are excluded. No additional taxes or fees are represented in this demo catalog.</p><p class="small">Fictional merchant prices. ${guide.joinedCount<guide.groupSize?`${guide.joinedCount} currently joined; estimates assume ${guide.groupSize} people. `:''}Estimates only: everyone’s needs and final availability still need checking. This is not a group recommendation or payment approval.</p></details></section>`;
}
const avatar=m=>`<span class="avatar identity-marker ${e(m.color??'blue')}" aria-hidden="true">${e(m.name?.[0]??'?')}</span>`;
const link=(href,label,kind='')=>`<a class="btn ${kind}" href="${e(href)}" data-nav>${e(label)}</a>`;
export const sheetDialog=(id,title,body)=>`<dialog id="${e(id)}" class="detail-sheet" aria-labelledby="${e(id)}-title"><div class="sheet-handle" aria-hidden="true"></div><header class="sheet-heading"><h2 id="${e(id)}-title">${e(title)}</h2><button type="button" class="sheet-close" data-sheet-close aria-label="Close ${e(title)}" autofocus>×</button></header><div class="sheet-content">${body}</div></dialog>`;
export const detailSheet=(id,title,body)=>`<button class="app-detail-trigger" type="button" data-sheet="${e(id)}" aria-haspopup="dialog">${e(title)}<span aria-hidden="true">›</span></button>`+sheetDialog(id,title,body);
const disclosure=(title,body)=>detailSheet('detail-'+title.toLowerCase().replace(/[^a-z0-9]+/g,'-'),title,body);
const quality=p=>`<p class="quality-line">★ ${p.quality.rating.toFixed(1)} · ${p.quality.reviewCount} reviews<br>${p.distanceMinutes} min to lifts · ${p.terms.refundPercent===100?'Free cancellation until '+date(p.terms.cancelBy):p.terms.refundPercent+'% refund by '+date(p.terms.cancelBy)}</p>`;
const packageTerms=p=>`${quality(p)}<p>${date(p.terms.startDate)} – ${date(p.terms.endDate)} · ${new Date(p.terms.startDate).getUTCFullYear()}</p><p>${p.privateBeds} separate beds · accommodation ${p.quality.accommodationQuality}/5 · ${p.capacity} people</p><p>${e(p.quality.includedAmenities.map(a=>({wifi:'Wi-Fi',hotTub:'Hot tub',breakfast:'Breakfast',shuttle:'Shuttle'})[a]??a).join(' · '))}</p><p>${p.parkingIncluded?'Parking included':'Shared parking fee'} · ${p.terms.refundPercent}% refund if cancelled by ${e(p.terms.cancelBy)}</p><p class="small">Merchant-reported fictional package attributes.</p>`;
const receipt=a=>a?`<div class="receipt">${Object.entries(a.components).filter(([,v])=>v>0).map(([k,v])=>`<div class="line"><span>${({sharedCents:'Shared lodging & parking',liftCents:'Lift ticket',rentalCents:'Rentals',bedCents:'Own-bed supplement'})[k]??'Package component'}</span><strong>${money(v)}</strong></div>`).join('')}<div class="line total"><span>Your exact share · USD</span><strong>${money(a.shareCents)}</strong></div></div>`:'';
const people=(group,persona)=>`<div class="social-list">${group.members.map(m=>`<div class="social-row">${avatar(m)}<div><strong>${e(m.name)}${m.id===persona?' · you':''}</strong><p>${e(m.constraintsConfirmed?statusLabel(m.commitmentStatus):'Needs to add')}</p></div><strong>${m.shareCents==null?'—':money(m.shareCents)}</strong></div>`).join('')}</div>`;
const faces=group=>`<div class="avatars" aria-label="${e(group.members.map(m=>m.name+': '+statusLabel(m.commitmentStatus)).join(', '))}">${group.members.map(m=>`<span class="avatar-progress" data-person="${e(m.id)}" data-commitment="${e(m.commitmentStatus)}">${avatar(m)}${['AUTHORIZED','CAPTURED'].includes(m.commitmentStatus)?'<span class="avatar-check" aria-hidden="true">✓</span>':''}</span>`).join('')}</div>`;
const socialPeople=(group,persona)=>`<div class="social-list">${group.members.map(m=>`<div class="social-row">${avatar(m)}<div><strong>${e(m.name)}${m.id===persona?' · you':''}</strong></div><span class="person-status ${m.commitmentStatus==='AUTHORIZED'||m.commitmentStatus==='CAPTURED'?'is-ready':''}">${e(m.constraintsConfirmed?statusLabel(m.commitmentStatus):'Needs to add')}</span></div>`).join('')}</div>`;
// One contribution per actual participant. Paths reflect saved approvals only.
const contributions=(group,persona,interactive=false)=>`<div class="collective-path contribution-path" style="--people:${group.members.length}"><div class="avatars contribution-people" aria-label="${e(group.members.map(m=>m.name+': '+statusLabel(m.commitmentStatus)).join(', '))}">${group.members.map(m=>{const ready=['AUTHORIZED','CAPTURED'].includes(m.commitmentStatus);return `${interactive?`<button type="button" class="contribution person-peek ${ready?'is-contributed':'is-open'}" data-sheet="person-${e(m.id)}" aria-haspopup="dialog" aria-label="View ${e(m.name)}’s shared status">`:`<div class="contribution ${ready?'is-contributed':'is-open'}">`}<span class="avatar-progress" data-person="${e(m.id)}" data-commitment="${e(m.commitmentStatus)}">${avatar(m)}${ready?'<span class="avatar-check" aria-hidden="true">✓</span>':''}</span><strong class="contribution-name">${e(m.name)}${m.id===persona?' · you':''}</strong><span class="person-status ${ready?'is-ready':''}">${e(m.constraintsConfirmed?statusLabel(m.commitmentStatus):'Needs to add')}</span>${interactive?'</button>':'</div>'}`;}).join('')}</div><svg class="contribution-merge" viewBox="0 0 400 4" preserveAspectRatio="none" aria-hidden="true">${group.members.map((m,i)=>{const x=i*400/group.members.length,end=(i+1)*400/group.members.length,ready=['AUTHORIZED','CAPTURED'].includes(m.commitmentStatus);return `<path class="${ready?'is-contributed':'is-open'}" d="M${x+2} 2 H${end-2}"/>`;}).join('')}</svg></div>`;
// These sheets contain only the already public participant projection.
const participantSheets=(group,persona)=>group.members.map(m=>sheetDialog('person-'+m.id,m.name+'’s part',`<section class="person-summary" data-contributed="${['AUTHORIZED','CAPTURED'].includes(m.commitmentStatus)}">${avatar(m)}<h3>${e(m.name)}${m.id===persona?' · you':''}</h3><p class="person-state">${e(m.constraintsConfirmed?statusLabel(m.commitmentStatus):'Needs to add')}</p>${m.shareCents==null?'':`<div class="person-share"><span>${m.id===persona?'Your':'Shared'} package share · USD</span><strong>${money(m.shareCents)}</strong></div>`}<p>Friends see shares and progress. Only you can see your private limits.</p></section>`)).join('');
const art=(sheet='')=>'<figure class="package-art" role="img" aria-label="AI-generated illustration of a fictional Vermont lodge"><figcaption>Illustrative image · fictional lodge</figcaption></figure>'+(sheet?'<button class="art-sheet-trigger" type="button" data-sheet="'+e(sheet)+'" aria-haspopup="dialog" aria-label="View full package terms"><span>Full terms <span aria-hidden="true">↗</span></span></button>':'');
export function comparisonFor(proposal,segment='best'){
 const label={best:'Best Value / Recommended',cost:'Lowest Cost',experience:'Best Experience'}[segment]??'Best Value / Recommended';
 return proposal.evaluations.find(x=>x.feasible&&x.comparisonLabels.includes(label))??null;
}

// Motion observes already-rendered projections. It never completes, saves or
// predicts a commercial operation. These snapshots stay in this page only.
export const motionTokens=Object.freeze({fast:140,standard:220,meaningful:400,easing:'cubic-bezier(.2,.8,.2,1)'});
const isCommitted=state=>state==='AUTHORIZED'||state==='CAPTURED';
export function interactionDelta(previous,next){
 const empty={people:[],links:[],events:[],outcomes:[],plan:false,prices:[],ready:false,verified:false,confirmed:false};
 if(!previous||previous.scope!==next.scope)return empty;
 const sameTerms=!!next.proposal&&previous.proposal===next.proposal;
 const people=sameTerms?next.people.filter(p=>{const old=previous.people.find(x=>x.id===p.id);return old&&!isCommitted(old.state)&&old.state!=='STALE'&&isCommitted(p.state);}):[];
 const links=sameTerms?next.people.slice(0,-1).filter((p,i)=>isCommitted(p.state)&&isCommitted(next.people[i+1].state)&&!previous.links.includes(p.id)).map(p=>p.id):[];
 const events=next.path===previous.path&&next.path==='/activity'?next.events.filter(p=>{const old=previous.events.find(x=>x.id===p.id);return !old||old.read!==p.read||old.resolved!==p.resolved;}).map(p=>({id:p.id,inserted:!previous.events.some(x=>x.id===p.id)})):[];
 const plan=next.path==='/proposal'&&previous.path===next.path&&next.segment!==previous.segment;
 return {people:people.map(p=>p.id),links,events,
  outcomes:sameTerms&&next.sagaKey===previous.sagaKey?next.outcomes.filter(p=>previous.outcomes.some(x=>x.id===p.id&&x.state!==p.state)).map(p=>p.id):[],
  plan,prices:plan?next.prices.map((p,i)=>p!==previous.prices[i]?i:null).filter(i=>i!==null):[],
  ready:sameTerms&&previous.ready===false&&next.ready===true,
  verified:sameTerms&&!!next.approvalKey&&previous.approvalKey===next.approvalKey&&previous.approval==='checking'&&next.approval==='verified',
  confirmed:sameTerms&&!!next.sagaKey&&previous.sagaKey===next.sagaKey&&previous.purchase!=='CONFIRMED'&&next.purchase==='CONFIRMED'};
}
export function createInteraction(root){
 let previous=null,context=null,animations=new Set();
 const reduce=()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 const query=selector=>root.querySelector(selector),all=selector=>[...root.querySelectorAll(selector)];
 const snapshot=ctx=>{
  const participants=all('main .avatars [data-person]').filter(el=>!el.closest('dialog'));
  const people=participants.map(el=>({id:el.dataset.person,state:el.dataset.commitment}));
  const events=all('.inbox-item[data-event-id]').map(el=>({id:el.dataset.eventId,read:el.dataset.eventRead,resolved:el.dataset.eventResolved}));
  return {scope:ctx.scope,path:ctx.path,proposal:query('[data-motion-proposal]')?.dataset.motionProposal??'',people,
   links:people.slice(0,-1).filter((p,i)=>isCommitted(p.state)&&isCommitted(people[i+1].state)).map(p=>p.id),events,
   outcomes:all('.settlement-path [data-person]').map(el=>({id:el.dataset.person,state:el.dataset.outcome})),
   sagaKey:query('[data-saga-key]')?.dataset.sagaKey,purchase:query('[data-purchase-state]')?.dataset.purchaseState,
   ready:query('.signature-waiting')?.dataset.ready==='true',approval:query('[data-approval-state]')?.dataset.approvalState,
   approvalKey:query('[data-approval-key]')?.dataset.approvalKey,
   segment:query('[data-plan-segment][aria-pressed="true"]')?.dataset.planSegment,
   option:query('[data-option]')?.dataset.option,prices:all('.plan-prices strong').map(el=>el.textContent),
   image:query('.plan-object .package-art')?.getAttribute('aria-label')};
 };
 const animate=(el,frames,duration=motionTokens.standard,delay=0)=>{
  if(!el||reduce()||typeof el.animate!=='function')return;
  const animation=el.animate(frames,{duration,delay,easing:motionTokens.easing,fill:'none'});
  animations.add(animation);animation.finished.then(()=>animations.delete(animation),()=>animations.delete(animation));
 };
 const resolve=(el)=>animate(el,[{transform:'scale(.9)',opacity:1},{transform:'scale(1)',opacity:1}],motionTokens.meaningful);
 function prepare(ctx){
  context=ctx;
  const visible=all('.inbox-item[data-event-id]').find(el=>el.getBoundingClientRect().bottom>0&&el.getBoundingClientRect().top<window.innerHeight);
  const active=query('[data-plan-segment][aria-pressed="true"]');
  return {old:previous,scrollY:window.scrollY,anchor:visible?{id:visible.dataset.eventId,top:visible.getBoundingClientRect().top}:null,segment:active?.getBoundingClientRect(),checking:query('.approval-path')?.cloneNode(true)};
 }
 function commit(ticket,ctx){
  const next=snapshot(ctx),old=ticket.old,delta=interactionDelta(old,next);
  previous=next;
  // A retained event, not a guessed feed height, anchors updates below the top.
  if(ctx.path==='/activity'&&old?.scope===ctx.scope&&old.path===ctx.path&&ticket.scrollY>24&&ticket.anchor){
   const anchor=all('.inbox-item').find(el=>el.dataset.eventId===ticket.anchor.id);
   if(anchor)window.scrollBy({top:anchor.getBoundingClientRect().top-ticket.anchor.top,behavior:'instant'});
  }
  for(const id of delta.people){const node=all('.avatar-progress').find(el=>el.dataset.person===id);resolve(node?.querySelector('.avatar'));resolve(node?.querySelector('.avatar-check'));}
  for(const id of delta.links){const node=all('.avatar-progress').find(el=>el.dataset.person===id);if(node&&!reduce()){node.classList.add('motion-link-resolve');node.addEventListener('animationend',()=>node.classList.remove('motion-link-resolve'),{once:true});}}
  for(const event of delta.events){const el=all('.inbox-item').find(el=>el.dataset.eventId===event.id);animate(el,event.inserted?[{transform:'translateY(-8px)',opacity:1},{transform:'none',opacity:1}]:[{opacity:1},{opacity:1}]);animate(el?.querySelector('.inbox-icon'),[{boxShadow:'0 0 0 5px var(--sand)'},{boxShadow:'0 0 0 0 transparent'}],motionTokens.meaningful);}
  if(delta.plan){
   const selected=query('[data-plan-segment][aria-pressed="true"]'),rect=selected?.getBoundingClientRect();
   if(rect&&ticket.segment&&!reduce()){
    const indicator=document.createElement('span');indicator.className='motion-selection';indicator.setAttribute('aria-hidden','true');
    const parent=selected.parentElement.getBoundingClientRect();indicator.style.cssText=`left:${rect.left-parent.left}px;top:${rect.top-parent.top}px;width:${rect.width}px;height:${rect.height}px`;
    selected.parentElement.append(indicator);const anim=indicator.animate([{transform:`translateX(${ticket.segment.left-rect.left}px)`},{transform:'translateX(0)'}],{duration:motionTokens.standard,easing:motionTokens.easing});animations.add(anim);anim.finished.then(()=>{indicator.remove();animations.delete(anim);},()=>{indicator.remove();animations.delete(anim);});
   }
   if(old.option!==next.option){for(const el of all('.plan-object>h2,.plan-object>.quality-line,.plan-object>.fit-line,.plan-object>.small'))animate(el,[{opacity:1,transform:'translateY(4px)'},{opacity:1,transform:'none'}]);}
   if(old.image!==next.image)animate(query('.plan-object .package-art'),[{opacity:1},{opacity:1}]);
   for(const i of delta.prices)animate(all('.plan-prices strong')[i],[{opacity:1,transform:'translateY(3px)'},{opacity:1,transform:'none'}]);
  }
  if(delta.ready){
   animate(query('.collective-path'),[{transform:'translateY(-3px)'},{transform:'none'}],motionTokens.meaningful);
   const path=query('.signature-waiting');if(path&&!reduce()){path.classList.add('motion-converge');path.addEventListener('animationend',()=>path.classList.remove('motion-converge'),{once:true});}
   animate(query('.signature-waiting .home-share'),[{opacity:1,transform:'translateY(5px)'},{opacity:1,transform:'none'}],300,80);
   animate(query('[data-action="review-finalize"]'),[{opacity:1},{opacity:1}],220,180);
  }
  if(delta.verified){
   // Brief, aria-hidden handoff overlay. New verified content is already visible;
   // no visual timer delays it or enables an operation.
   if(ticket.checking&&!reduce()){
    const overlay=ticket.checking;overlay.classList.add('verified-arrival');overlay.querySelector('.verification-node')?.classList.add('is-verified');
    const end=overlay.querySelector('.verification-destination');if(end)end.textContent='✓';
    query('.transaction')?.append(overlay);
    const anim=overlay.animate([{opacity:.9,transform:'scale(.85)'},{opacity:0,transform:'scale(1)'}],{duration:motionTokens.meaningful,easing:motionTokens.easing});animations.add(anim);anim.finished.then(()=>{overlay.remove();animations.delete(anim);},()=>{overlay.remove();animations.delete(anim);});
   }
   resolve(query('.commit-amount'));animate(query('.app-heading'),[{opacity:1},{opacity:1}]);
  }
  for(const id of delta.outcomes){const el=all('.settlement-path [data-person]').find(el=>el.dataset.person===id);resolve(el?.querySelector('.avatar'));animate(el?.querySelector('.outcome'),[{opacity:1},{opacity:1}]);}
  // Arrival means this already verified view was opened, not another capture.
  if(delta.confirmed||next.purchase==='CONFIRMED'&&(!old||old.scope!==next.scope||old.path!==next.path)){
   animate(query('.app-heading'),[{opacity:1,transform:'translateY(3px)'},{opacity:1,transform:'none'}],300);
   animate(query('.confirmed-card .package-art'),[{opacity:.8},{opacity:1}],300);
   for(const el of all('.confirmed-card .avatar-progress'))resolve(el);
  }
  for(const form of all('#mandate-form,#preferences-form,#auto-finalize-form'))form.dataset.motionInitial=formValue(form);
 }
 const formValue=form=>JSON.stringify([...form.elements].filter(el=>el.name&&el.name!=='confirm').map(el=>[el.name,el.type==='checkbox'?el.checked:el.value]));
 root.addEventListener('change',event=>{
  const form=event.target.closest('#mandate-form,#preferences-form,#auto-finalize-form');
  if(form){form.dataset.unsaved=String(formValue(form)!==form.dataset.motionInitial);const row=event.target.closest('.switch-row');animate(row,[{backgroundColor:'var(--sand)'},{backgroundColor:'transparent'}],motionTokens.fast);}
 });
 window.matchMedia('(prefers-reduced-motion: reduce)').addEventListener?.('change',event=>{if(event.matches){for(const animation of animations)animation.cancel();animations.clear();for(const el of all('.motion-link-resolve,.motion-converge'))el.classList.remove('motion-link-resolve','motion-converge');for(const el of all('.verified-arrival,.motion-selection'))el.remove();}});
 return {prepare,commit};
}
export function createAppViews(context){
 const base=createViews(context),{session,draft,statementInput,error='',path='/',planSegment='best',needsMode='describe',needsAmounts={maximum:'',preferred:null}}=context;
 const mine=group=>group.members.find(m=>m.id===session.persona);
 function shell(content){
  const focused=path.startsWith('/commit')||['/constraints','/start','/join','/demo','/replay'].includes(path);
  const nav=session.hasGroup&&session.persona!=='merchant'&&!focused;
  const active=path==='/proposal'?'Plan':path==='/activity'?'Activity':['/you','/agent','/updates'].includes(path)?'You':'Group';
  const paths={Group:'/group',Plan:'/proposal',Activity:'/activity',You:'/you'};
  const icons={Group:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M17 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 5"/>',Plan:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="M8 8h8M8 12h8M8 16h5"/>',Activity:'<path d="M4 5h16v14H4Z M4 13h5l2 3h2l2-3h5"/>',You:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>'};
  const logo=base.header().match(/<a class="logo"[\s\S]*?<\/a>/)[0].replace('href="/"','href="'+(session.hasGroup?'/group':'/')+'"');
  const back=path==='/constraints'?'/you':path.startsWith('/commit')?'/proposal':session.hasGroup?'/group':'/';
  return `<div class="shell app-shell ${nav?'has-app-nav':'focused-shell'}"><a class="skip-link" href="#main">Skip to content</a><header class="app-header ${nav?'compact-app-header':''}">${focused?`<a class="back-link" href="${back}" data-nav>← Back</a>`:logo}${nav?`<a class="profile-dot" href="/you" data-nav aria-label="Your profile">${e(session.personas.find(p=>p.id===session.persona)?.name?.[0]??'?')}</a>`:''}</header>${nav?`<nav class="app-nav" aria-label="Main navigation">${Object.entries(paths).map(([label,href])=>`<a href="${href}" data-nav ${active===label?'aria-current="page"':''}><svg viewBox="0 0 24 24" aria-hidden="true">${icons[label]}</svg><span>${label}</span></a>`).join('')}</nav>`:''}<main id="main" tabindex="-1">${error?`<div class="notice error" role="alert">${e(error)}</div>`:''}${content}</main></div>`;
 }
 function groupPage(group,offer=''){
  const m=mine(group),p=group.proposal,waiting=group.members.filter(x=>x.commitmentStatus!=='AUTHORIZED').map(x=>e(x.name));
  let state='Tell Commit what matters to you',body='Your budget and private needs stay yours.',action=link('/constraints','Set my needs');
  if(m?.constraintsConfirmed){
   if(!p?.feasible){state=p?'Let’s find another fit':'Let’s find your group’s fit';body='Everyone’s confirmed hard limits stay in place.';action=`<button class="btn full" data-action="solve" ${group.members.every(x=>x.constraintsConfirmed)?'':'disabled'}>Find our fit</button>`;}
   else if(group.ready){state='Everyone’s in 🎉';body=`${group.committedCount} of ${group.members.length} committed`;action=group.autoFinalize?'<p role="status">Everyone approved. Commit is finalizing the purchase.</p>':m.organizer?'<button class="btn full" data-action="review-finalize">Finalize group purchase</button>':'<p>Your organizer can finalize the purchase.</p>';}
   else if(m.commitmentStatus==='AUTHORIZED'){state='Almost there';body=`Waiting for ${waiting.join(', ')}.`;action='';}
   else if(['ORDER_CREATED','PAYER_APPROVED','NEEDS_VERIFICATION'].includes(m.commitmentStatus)){state='Your approval is in progress';body='Review your approval and the latest checked status.';action=link('/commit','Continue my approval','full');}
   else {state=group.appliedOffer?'Your new approval is needed':'Your approval is needed';body='A plan that fits your group is ready.';action=link('/commit','Review my share','full');}
  }
  if(group.saga?.state==='CONFIRMED')return `${heading(group.name,p?.package?date(p.package.terms.startDate)+' – '+date(p.package.terms.endDate):'Purchase confirmed')}${faces(group)}<section class="home-state"><h2>Your group payment is confirmed ✓</h2><p>${e(group.saga.packageName)} · Everyone confirmed</p><div class="home-share"><span>Group total</span><strong>${money(group.saga.totalCents)}</strong></div>${group.appliedOffer?'<p class="savings-inline">You saved '+money(group.appliedOffer.savingsCents)+' together</p>':''}${link('/proposal','View plan','full')}<p class="payment-completion-note">Verified Sandbox payments. No accommodation reservation has been placed.</p><p class="small muted">Fictional merchant · test money only.</p></section>${socialPeople(group,session.persona)}${link('/waiting','Receipt / purchase details','secondary')}`;
  if(group.saga)return sagaProgress(group,true);
  if(group.captureDetected){state='Your payment needs review';body='An unexpected charge was detected. The group is not ready to finalize.';action=link('/waiting','Review payment details','full');}
  const offerNeedsAction=offer&&(group.availableOffers?.length||group.appliedOffer&&m.commitmentStatus!=='AUTHORIZED');
  return `${offerNeedsAction?'':'<div class="group-space group-composition social-group">'}${offerNeedsAction?heading(group.name,p?.package?date(p.package.terms.startDate)+' – '+date(p.package.terms.endDate):'Your next plan, together'):'<div class="group-context">'+(p?.package?art():'')+heading(group.name,p?.package?date(p.package.terms.startDate)+' – '+date(p.package.terms.endDate):'Your next plan, together')+'</div>'}${offerNeedsAction?faces(group)+offer:`<section class="home-state signature-group" data-motion-proposal="${e(p?.id??'')}"><div class="shared-progress-title"><h2>${state}</h2><p class="group-count" aria-label="${group.committedCount} of ${group.members.length} committed"><strong>${group.committedCount} <span>of</span> ${group.members.length}</strong> <span class="count-caption">committed</span></p></div><p class="people-instruction">Your people <span>Tap a person for their part ↗</span></p>${contributions(group,session.persona,true)}<p class="current-status shared-destination">${body}</p>${m?.shareCents!=null?`<button class="home-share personal-receipt" type="button" data-sheet="detail-group-payment-details" aria-haspopup="dialog" aria-label="View your share and group payment details"><span>Your share${m.commitmentStatus==='AUTHORIZED'?' · held, not charged':''}</span><strong>${money(m.shareCents)}</strong><span class="card-chevron" aria-hidden="true">↗</span><span class="share-tap-cue">Share details</span></button>`:''}${action}</section>${offer}`}${p?.package?`<a class="plan-peek" href="/proposal" data-nav><div><span class="small">Your plan</span><strong>${e(p.package.name)}</strong><span>${money(p.totalCents)} group total</span></div><span aria-hidden="true">→</span></a>`:''}${offerNeedsAction?'':'</div>'}${disclosure('Group & payment details',`${offerNeedsAction?socialPeople(group,session.persona):''}${people(group,session.persona)}<p>${e(group.goal)}</p><p>Authorized · ${money(group.authorizedCents)}<br>Captured · ${group.captureDetected?'Needs review':money(group.capturedCents)}</p><p>Group approval window ends ${time(group.commitmentDeadline)}.</p><p>Friends see shares and progress. Only you can see your private limits.</p>`)}${offerNeedsAction?'':participantSheets(group,session.persona)}${session.joinedIdentity&&m?.organizer?`<section class="app-section"><h2>Invite your friends</h2><button class="btn secondary" data-action="invite-create">Create invite link</button><p id="invite-output" role="status"></p></section>`:''}`;
 }
 function proposalPage(group,offer=''){
  const p=group.proposal;if(!p)return heading('Your plan','Confirm everyone’s needs to find your group’s fit.')+link('/group','Back to Group');
  const selected=comparisonFor(p,planSegment),recommended=p.evaluations.find(x=>x.package.id===p.package?.id),pkg=selected?.package;
  const label={best:'Best fit',cost:'Lowest cost',experience:'Best experience'}[planSegment];
  const segments=`<div class="segments" role="group" aria-label="Compare plans">${[['best','Best fit'],['cost','Lowest cost'],['experience','Best experience']].map(([value,text])=>`<button data-plan-segment="${value}" aria-pressed="${planSegment===value}">${text}</button>`).join('')}</div>`;
  let panel=heading('No available option','No option in this category meets the confirmed hard limits.');
  if(pkg){const current=pkg.id===p.package?.id,delta=selected.totalCents-(recommended?.totalCents??selected.totalCents);panel=`<section class="card plan-object" aria-labelledby="plan-title" data-option="${e(pkg.id)}"><div class="plan-image-action">${art('detail-full-package-terms')}</div><p class="eyebrow">${label}${current?' · Current group plan':''}</p><h2 id="plan-title">${e(pkg.name)}</h2>${quality(pkg)}${selected.comparisonLabels.length===3?'<p class="same-option-note">Same package for all three picks.</p>':''}<div class="plan-prices"><div><span>Group total</span><strong>${money(selected.totalCents)}</strong></div><div><span>Your share</span><strong>${selected.ownAllocation?money(selected.ownAllocation.shareCents):'Not available'}</strong></div></div><p class="fit-line">✓ Meets every confirmed hard limit</p>${selected.ownChecks?.filter(x=>x.passed&&!['hardMax','confirmed'].includes(x.key)).slice(0,3).map(x=>`<p class="fit-line">✓ ${e(ruleText(x))}</p>`).join('')??''}<p class="small">${current?'':`Comparison only · ${delta<0?'Save '+money(-delta):delta>0?'Costs '+money(delta)+' more':'Same price'} compared with the current plan. ${pkg.distanceMinutes-(p.package?.distanceMinutes??pkg.distanceMinutes)>0?'Farther from the lifts.':''} Each person’s approval stays bound to the current plan.`}</p>${current?(group.saga?link('/waiting','View purchase','full'):link('/commit','Review my '+money(mine(group)?.shareCents??0)+' share','full')):''}${disclosure('Why Commit chose this',`<p>${e(pkg.name)} meets every confirmed hard limit and quality floor. ${planSegment==='best'?'It ranks first for best value, considering price, declared quality, preference fit and fairness.':planSegment==='cost'?'It has the lowest total among feasible options.':'It has the highest declared quality among feasible options.'}</p><p>Shared lodging and parking are split equally; everyone pays their own add-ons. Private limits stay private.</p>${selected.comparisonLabels.length>1?`<p>This package also qualifies as ${selected.comparisonLabels.filter(x=>x!==({best:'Best Value / Recommended',cost:'Lowest Cost',experience:'Best Experience'}[planSegment])).map(e).join(' and ')}.</p>`:''}`)}${disclosure('Full package terms',packageTerms(pkg)+receipt(selected.ownAllocation)+`<p class="small">Proposal version ${p.revision}. This comparison does not change the approved commercial envelope.</p>`)}</section>`;}
  const unavailable=p.evaluations.filter(x=>!x.feasible);
  return `${heading('Your plan')}${segments}<div id="comparison-panel" aria-live="polite">${panel}</div>${offer}${disclosure('Everyone’s share',people(group,session.persona))}${unavailable.length?disclosure('Unavailable for this group · '+unavailable.length,unavailable.map(x=>base.comparisonCard(x,p)).join('')):''}`;
 }
 function constraintsPage(own,guide=null){
  const p=draft?.parsed;
  const rules=kind=>p[kind].map((r,i)=>`<li>${e(ruleText(r))}</li>`).join('');
  const sharing=kind=>p[kind].map((r,i)=>`<label class="switch-row"><span>Share ${e(ruleText(r))}</span><input type="checkbox" role="switch" name="public-${kind}-${i}" ${r.visibility==='PUBLIC'?'checked':''}></label>`).join('');
  const budgeting=needsMode==='budget'||(draft&&p.hardMax===null),statement=statementInput??own.statement;
  const privacy='<p class="needs-private-label">🔒 Private to you</p>';
  if(budgeting)return `<div class="guided-needs">${needsPath(2)}${heading('Choose your limit','Your share, your firm maximum.')}${privacy}${priceContext(guide)}<form id="needs-budget-form" class="needs-budget"><label class="field"><span>Maximum spend · USD</span><input name="hardMax" type="number" inputmode="decimal" min="0" max="100000" step="0.01" ${needsAmounts.maximum!==''?'value="'+e(needsAmounts.maximum)+'"':''} required placeholder="Your firm maximum"><small>For your individual share of the listed package. Commit must never exceed this.</small></label><details class="app-details comfortable-preference" ${needsAmounts.preferred!==null&&needsAmounts.preferred!==''||p?.preferredMax!=null?'open':''}><summary>Add a comfortable amount · optional</summary><label class="field"><span>Comfortable spend · optional</span><input name="preferredMax" type="number" inputmode="decimal" min="0" max="100000" step="0.01" value="${e(needsAmounts.preferred??p?.preferredMax??'')}" placeholder="Your preferred amount"><small>A preference, not a spending limit.</small></label></details><details class="app-details"><summary>Your needs so far</summary><label class="field"><span>Must-haves & preferences</span><textarea name="statement" maxlength="1700" placeholder="Anything this plan needs to work for you?">${e(statement)}</textarea></label>${draft?`<ul>${rules('requirements')}${rules('preferences')}</ul>`:''}<p class="small">${draft?'Interpreted as a draft; nothing is confirmed yet.':'You can leave this blank if you have no additional needs.'}</p></details><p class="small">We’ll review these together before saving. Your maximum and unshared needs stay private. This does not approve a payment.</p><button type="submit" class="btn full">Review my boundaries</button><button type="button" class="btn subtle full" data-action="needs-describe">Back to my needs</button></form></div>`;
  return `<div class="guided-needs">${needsPath(draft?3:1)}${heading(draft?'Here’s what I understood':'Let’s find your fit',draft?'Your boundaries, for your individual package share.':'A sentence or a quick choice is enough to start.')}${privacy}${draft?`<form id="confirm-form" class="needs-review"><h2>Review your needs</h2>${p.clarifications.length?`<div class="notice warning" role="status">${p.clarifications.map(e).join('<br>')}<p>Edit your words before confirming.</p></div>`:''}<section><h2>Must have</h2><ul><li>${p.hardMax==null?'Add your hard maximum':'Up to '+money(p.hardMax*100)}</li>${rules('requirements')}</ul></section><section><h2>Nice to have</h2><ul>${p.preferredMax==null?'':'<li>Around '+money(p.preferredMax*100)+'</li>'}${rules('preferences')||(!p.preferredMax?'<li>No preferences added</li>':'')}</ul></section><details class="app-details"><summary>Adjust amounts & sharing</summary><label class="field"><span>Absolute maximum · always private</span><input name="hardMax" type="number" inputmode="decimal" min="0" max="100000" step="0.01" required value="${p.hardMax??''}"></label><label class="field"><span>Preferred budget · always private</span><input name="preferredMax" type="number" inputmode="decimal" min="0" max="100000" step="0.01" value="${p.preferredMax??''}"></label>${sharing('requirements')}${sharing('preferences')}<p class="small">Only selected individual needs are shared. Your budget is always private.</p></details><p class="small">Saving asks the group to find a fresh fit. It does not approve a payment.</p><button class="btn full" type="submit" ${p.clarifications.length?'disabled':''}>Looks right ✓</button><button class="btn subtle full" type="button" data-action="edit-interpretation">Edit my words</button></form>${priceContext(guide)}`:`${priceContext(guide)}<form id="interpret-form" class="needs-editor"><label class="field"><span>What would make this work for you?</span><textarea name="statement" required minlength="10" maxlength="1700" placeholder="I need rentals, and I’m flexible otherwise.">${e(statement)}</textarea></label><div class="needs-prompts" aria-label="Add a need to your words"><button type="button" data-action="needs-prompt" data-phrase="I need rentals.">I need rentals +</button><button type="button" data-action="needs-prompt" data-phrase="Having my own bed is a hard requirement.">My own bed +</button><button type="button" data-action="needs-prompt" data-phrase="I can drive.">I can drive +</button><button type="button" data-action="needs-prompt" data-phrase="I am flexible with no extra needs.">I’m flexible +</button></div><p class="small">Know your maximum? Include it here to skip the budget question.</p><button class="btn full" type="submit">Understand my needs</button><button class="btn secondary full" type="button" data-action="needs-price-first">Not sure — show me prices first</button>${session.aiMode==='offline-demo'?'<p class="small muted">Local demo interpretation</p>':''}</form>`}</div>`;
 }
 function commitPage(group,ledger){
  if(group.saga)return sagaProgress(group,true);
  const c=ledger.current,pkg=c?.envelope?.packageTerms??group.proposal?.package,m=mine(group),old=ledger.history.find(x=>x.authorizationId&&['STALE','VOIDED'].includes(x.state));
  const approved=c?.state==='AUTHORIZED'&&m?.commitmentStatus==='AUTHORIZED';
  const fresh=!!old&&!approved&&c?.state!=='VOIDED';
  if(fresh&&new URLSearchParams(typeof location==='undefined'?'':location.search).get('review')!=='commitment'){
   const previous=old.authorizedAmountCents??old.amountCents;
   return `${heading('Your price changed')}<section class="card stale-card"><p class="eyebrow">A fresh yes to better terms</p><div class="term-comparison"><div><span>Previously approved</span><strong>${money(previous)}</strong></div><div><span>Your new share</span><strong>${money(c?.amountCents??m.shareCents)}</strong></div></div>${previous>(c?.amountCents??m.shareCents)?`<p class="savings-inline">You save ${money(previous-(c?.amountCents??m.shareCents))}</p>`:''}<p>We won’t reuse your previous approval. Review the new amount before committing again.</p>${link('/commit?review=commitment','Review '+money(c?.amountCents??m.shareCents)+' commitment','full')}${disclosure('Why do I need to approve again?',`<p>Your approval binds to the exact proposal/version, merchant, package, maximum amount, material attributes, dates and refund conditions. A material change requires fresh approval, even at a lower price.</p><h3>Previous terms</h3>${old.envelope?.packageTerms?packageTerms(old.envelope.packageTerms):''}<p>Proposal version ${old.proposalVersion}. ${e(statusLabel(old.state))}. A previous hold may still exist; PayPal controls release timing.</p><h3>New terms</h3>${pkg?packageTerms(pkg):''}`)}</section>`;
  }
  if(!c||!pkg||c.state==='STALE')return heading('Review the changed plan','Your previous approval won’t be used.')+link('/proposal','Review current plan');
  const pending=c.reconciliation==='CHECKING'||(c.reconciliation!=='ATTENTION'&&['ORDER_CREATED','PAYER_APPROVED'].includes(c.state));
  let action='';
  if(c.state==='NOT_STARTED')action=`<button class="btn full" data-action="commit-create" data-proposal-id="${e(group.proposal.id)}" ${group.paymentsAvailable?'':'disabled'}>Approve ${money(c.amountCents)} with PayPal ↗</button>`;
  else if(approved)action=link('/waiting','See group progress','full');
  else if(c.state==='VOIDED')action='<p>This authorization was released. Confirm your needs and find a fresh plan before approving again.</p>'+link('/constraints','Review my needs','secondary');
  else if(pending){action=`${c.approvalUrl?`<a class="payment-link" href="${e(c.approvalUrl)}" target="_blank" rel="noopener noreferrer">Continue in official PayPal Sandbox ↗</a>`:''}<p class="small">After approving in PayPal, Commit checks your exact approval automatically. You can return here or close the app.</p>`;}
  else action='<p role="status">Your payment status needs review. No additional charge is being requested. The latest recorded status appears in Payment details.</p>';
  return `${heading(approved?'You’re committed ✓':pending?'Checking your approval…':c.reconciliation==='ATTENTION'||c.state==='FAILED'?'We need your attention':'Your commitment')}<section class="transaction ${pending?'checking-transaction':''}" data-approval-state="${approved?'verified':pending?'checking':'unconfirmed'}" data-approval-key="${e(c.id)}" data-motion-proposal="${e(group.proposal?.id??'')}" data-provider-approved="${c.state==='PAYER_APPROVED'}">${pending?`<div class="checking-progress"><div class="approval-path" aria-hidden="true"><span class="provider-node">${c.state==='PAYER_APPROVED'?'✓':'↗'}</span><span class="verification-link"><i></i></span><span class="verification-node"><svg viewBox="0 0 24 24"><path d="M17 6a8 8 0 1 0 0 12l3-3"/></svg></span><span class="verification-future-link"></span><span class="verification-destination"></span></div><div class="approval-labels"><div><strong>PayPal</strong><span>${c.state==='PAYER_APPROVED'?'Buyer approved':'Awaiting approval'}</span></div><div><strong>Commit</strong><span>Verifying…</span></div><div><strong>Confirmation</strong><span>Not verified</span></div></div><p class="pending-state" role="status">Your approval is not confirmed yet.</p></div>`:''}${pending?'<div class="approval-envelope">':''}<div class="commit-amount">${money(c.amountCents)}</div>${pending?'<div class="approval-package">':''}<h2>${e(pkg.name)}</h2><p>${date(pkg.terms.startDate)} – ${date(pkg.terms.endDate)}</p>${pending?'</div></div>':''}<ul class="protected-list"><li>Exact dates</li><li>${pkg.terms.refundPercent}% refund by ${date(pkg.terms.cancelBy)}</li><li>Maximum commitment ${money(c.amountCents)} · USD</li></ul><div class="hold-note"><strong>${group.captureDetected?'Payment needs review':approved?'Held, not charged':pending?'Approval not confirmed':c.state==='VOIDED'?'Hold released':c.state==='NOT_STARTED'?'No payment approved yet':'Payment needs review'}</strong><p>${group.captureDetected?'An unexpected charge needs review. The group is not ready to finalize.':'Commit finalizes only after every required current approval is valid.'}</p></div>${group.appliedOffer&&group.appliedOffer.cleanupState!=='COMPLETE'?'<div class="notice warning">Previous holds still need verified release. New approvals are blocked until cleanup completes.</div>':''}${action}<p class="small muted">Official PayPal-hosted Sandbox checkout · test money only.</p>${disclosure('View full terms',packageTerms(pkg)+receipt(group.proposal?.ownAllocation)+`<p>Proposal version ${c.proposalVersion} · exact approved ceiling. Your approval binds to this merchant, package, amount, dates, material attributes and refund terms. Authorization does not guarantee a successful charge.</p>`)}${disclosure('Payment details',`<p>${e(statusLabel(c.state))}. Last verified ${time(c.verifiedAt)}. Authorization expiry ${time(c.expiresAt)}.</p>${c.authorizationId&&c.state!=='VOIDED'?`<p>Releasing your hold removes it from group readiness. PayPal determines release timing.</p><button class="btn subtle" data-action="commit-void" data-commitment-id="${e(c.id)}">Release my authorization</button>`:''}${ledger.history.length?`<h3>Earlier commitments</h3>${ledger.history.map(x=>`<p>${money(x.authorizedAmountCents??x.amountCents)} · proposal version ${x.proposalVersion} · ${e(statusLabel(x.state))}</p>${x.authorizationId&&!['REFUNDED','CAPTURED','VOIDED'].includes(x.state)?`<button class="btn subtle" data-action="commit-void" data-commitment-id="${e(x.id)}">Release previous authorization</button>`:''}`).join('')}`:''}`)}</section>`;
 }
 function waitingPage(group,offer=''){if(group.saga)return sagaProgress(group,true);return `${heading(group.ready?'Everyone’s in 🎉':'Almost there',group.committedCount+' of '+group.members.length+' committed')}${offer}${group.captureDetected?'<div class="notice error">An unexpected charge needs review. The group is not ready to finalize.</div>':''}<section class="waiting-state signature-waiting" data-ready="${group.ready}" data-motion-proposal="${e(group.proposal?.id??'')}"><h2>${e(group.proposal?.package?.name??group.name)}</h2>${contributions(group,session.persona)}<div class="collective-outcome">${group.ready?`<div class="home-share"><span>Group total</span><strong>${money(group.authorizedCents)}</strong></div>${group.autoFinalize?'<p role="status">Everyone approved. Commit is finalizing the purchase.</p>':mine(group)?.organizer?'<button class="btn full" data-action="review-finalize">Finalize group purchase</button>':'<p>Your organizer can finalize.</p>'}`:`<p>Waiting for ${group.members.filter(x=>x.commitmentStatus!=='AUTHORIZED').map(x=>e(x.name)).join(', ')}.</p>${mine(group)?.commitmentStatus==='AUTHORIZED'?`<p class="fit-line own-authorization"><span>Your </span><strong>${money(mine(group).shareCents)}</strong><span> share is authorized ✓</span></p><p class="waiting-assurance">Held, not charged. The group is not purchased yet.</p>`:link('/commit','Review my share','full')}`}</div>${group.proposal?.package?`<a class="waiting-plan-link" href="/proposal" data-nav><span>View the shared plan</span><strong>${e(group.proposal.package.name)}</strong><span aria-hidden="true">→</span></a>`:''}${disclosure('Payment details',`${people(group,session.persona)}<p>Authorized · ${money(group.authorizedCents)}<br>Captured · ${group.captureDetected?'Needs review':money(group.capturedCents)}</p><p>Approval window ends ${time(group.commitmentDeadline)}. No purchase is confirmed until all payments are verified.</p>`)}</section>`;}
 function sagaProgress(group){
  const s=group.saga;if(!s)return '';
  const done=s.state==='CONFIRMED',compensated=s.state==='COMPENSATED',recovery=['CAPTURE_FAILED','COMPENSATING','COMPENSATION_FAILED','REQUIRES_MANUAL_REVIEW'].includes(s.state),pkg=group.proposal?.package;
  const title=done?'Group payment confirmed ✓':compensated?'Nothing was finalized':recovery?'We couldn’t complete the purchase':'Finalizing your purchase';
  const accounting=`<p>Captured · gross ${money(s.capturedCents)}<br>Refunds confirmed · ${money(s.refundedCents)}</p><p class="small">Gross captures include payments later refunded. PayPal confirmation does not mean instant bank or card settlement.</p>`;
  const rows=s.participants.map(p=>{const o=participantOutcome(p);return `<div class="social-row" data-outcome="${e(o.text)}" data-person="${e(p.userId)}">${s.state==='CAPTURING'&&o.text==='✓ Confirmed'?'<span class="avatar settlement-verified" aria-hidden="true">✓</span>':avatar(p)}<div class="settlement-person"><strong>${e(p.name)}</strong><p class="outcome ${o.tone}">${e(o.text)}${recovery&&o.text==='✓ Confirmed'?' · awaiting refund':''}</p></div><strong class="settlement-amount">${money(p.amountCents)}</strong></div>`;}).join('');
  return `${heading(title,s.packageName)}${done?'<p class="payment-completion-note">Sandbox payments verified. No accommodation reservation.</p>':''}<section class="card ${done?'confirmed-card':'saga-card'}" data-purchase-state="${e(s.state)}" data-motion-proposal="${e(group.proposal?.id??'')}" data-saga-key="${e(s.id)}">${done?art():''}${pkg?`<p>${date(pkg.terms.startDate)} – ${date(pkg.terms.endDate)}</p>`:''}${done?`<div class="home-share"><span>Group total</span><strong>${money(s.totalCents)}</strong></div>${group.appliedOffer?`<p class="savings-inline">You saved ${money(group.appliedOffer.savingsCents)} together</p>`:''}${faces(group)}<p class="fit-line">Everyone confirmed ✓</p>${link('/group','View Group','full')}`:`<p role="status">${compensated?'Completed charges were refunded and remaining authorizations released. Your bank or card may take additional time.':recovery?'Commit is reversing the payments that went through. Pending or uncertain results are not confirmed reversals.':'Each approved share is processed separately. The group is confirmed only after all payments are verified.'}</p>${recovery||compensated?accounting:''}<div class="social-list settlement-path">${rows}</div>${recovery&&mine(group)?.organizer?`<button class="btn full" data-action="resume-saga" data-saga-id="${e(s.id)}">Continue payment recovery</button><p class="small">Continues the existing saved recovery operations. Unresolved outcomes may require manual review.</p>`:''}${compensated?link('/constraints','Review needs for a fresh plan','secondary'):''}`}${disclosure(done?'Receipt / purchase details':'Purchase details',`${!recovery&&!compensated?accounting:''}<p>Proposal version ${s.proposalVersion} · ${e(s.packageName)}</p>${done?`<div class="social-list">${rows}</div>`:''}<p>No accommodation reservation has been placed. The merchant and stay are fictional.</p>${s.negativeTest?'<p>Demo review: a controlled Sandbox failure was selected for this purchase.</p>':''}`)}<p class="small muted">Sandbox demo · fictional Summit Weekend merchant · no accommodation reservation.</p></section>`;
 }
 function demoPage(group,ledger){return `${heading('Demo controls','Development tools, separate from your group’s current product view.')}<section class="card"><label class="field"><span>Demo as</span><select id="persona" ${session.joinedIdentity?'disabled':''}>${session.personas.map(p=>`<option value="${e(p.id)}" ${p.id===session.persona?'selected':''}>${e(p.name)}</option>`).join('')}</select></label><p>${session.aiMode==='offline-demo'?'Offline demo · limited local interpretation. No external AI call is made.':'External AI interpretation is configured.'}</p>${link('/replay','Verified demo replay','secondary')}<p class="small">Replay is historical and read-only, separate from current financial status.</p>${group?disclosure('Provider diagnostics',`<p>Proposal version ${group.proposal?.revision??'—'}</p><button class="btn subtle" data-action="refresh-payments" ${group.paymentsAvailable?'':'disabled'}>Check PayPal status</button>${ledger?.current?.authorizationId?`<button class="btn subtle" data-action="commit-verify" data-commitment-id="${e(ledger.current.id)}">Verify my authorization</button>`:''}`):''}${session.joinedIdentity?'':`<div class="buttons"><button class="btn secondary" data-action="demo">Try seeded demo</button><button class="btn secondary" data-action="offer-demo">Try February offer demo</button></div>`}</section>`;}
 return {...base,shell,groupPage,proposalPage,constraintsPage,commitPage,waitingPage,sagaProgress,demoPage,finalizeReview:g=>base.finalizeReview(g).replace(' · plan version '+g.proposal.revision,'')};
}
